sql.where:
r.del_flag = 0

    AND r.factory_id = #{dto.factoryId}


    AND r.location_id = #{dto.locationId}


    AND r.vehicle_type = #{dto.vehicleType}


    AND r.plate_number LIKE CONCAT('%', #{dto.plateNumber}, '%')


    AND r.in_out_type = #{dto.inOutType}


    AND r.emp_name LIKE CONCAT('%', #{dto.empName}, '%')


    AND r.release_date >= #{dto.releaseDateStart}


    AND r.release_date <= #{dto.releaseDateEnd}


    AND r.release_time >= #{dto.releaseTimeStart}


    AND r.release_time <= #{dto.releaseTimeEnd}


    AND r.id IN

        #{item}
